import java.util.Scanner;

public class Main {
    static int boluvchilarSoni(int n) {
        int soni = 0;
        for (int i = 1; i < n; i++) {
            if (n % i == 0) {
                soni++;
            }
        }
        return soni;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        System.out.println(boluvchilarSoni(n));
    }
}

